import{_ as a,o as t,a as o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Configure Load Balancing","description":"","frontmatter":{},"headers":[],"relativePath":"performance/configure-load-balancing.md","filePath":"performance/configure-load-balancing.md","lastUpdated":1789464754000}'),s={name:"performance/configure-load-balancing.md"};function n(d,e,i,c,h,l){return t(),o("div",null,e[0]||(e[0]=[r(`<h1 id="configure-load-balancing" tabindex="-1">Configure Load Balancing <a class="header-anchor" href="#configure-load-balancing" aria-label="Permalink to &quot;Configure Load Balancing&quot;">​</a></h1><p>Bagisto runs on several web servers behind a load balancer when every server shares the state a request can touch: the database, sessions, caches, maintenance mode, queued jobs, files and the search cluster. This page sets up each of those, then deploys, checks the result and outlines the same setup on AWS.</p><h2 id="when-you-need-it" tabindex="-1">When You Need It <a class="header-anchor" href="#when-you-need-it" aria-label="Permalink to &quot;When You Need It&quot;">​</a></h2><p>Use it when one web server is no longer enough, or when the store must keep running if a server fails. This is what the servers must share, with the shipped default and what to use instead:</p><table tabindex="0"><thead><tr><th>Concern</th><th>Shipped default</th><th>On more than one server</th></tr></thead><tbody><tr><td>Database</td><td><code>DB_HOST</code> in <code>.env</code></td><td>One database server or managed database that every web server connects to</td></tr><tr><td>Sessions</td><td><code>SESSION_DRIVER=database</code></td><td><code>database</code> or <code>redis</code>, never <code>file</code></td></tr><tr><td>Application and repository cache</td><td><code>CACHE_STORE=database</code></td><td><code>database</code> or <code>redis</code>, never <code>file</code></td></tr><tr><td>Full page cache</td><td><code>RESPONSE_CACHE_DRIVER=file</code></td><td>A shared Redis store of its own</td></tr><tr><td>Maintenance mode</td><td><code>APP_MAINTENANCE_DRIVER=file</code></td><td><code>cache</code>, with <code>APP_MAINTENANCE_STORE</code> set to a shared store</td></tr><tr><td>Queue</td><td><code>QUEUE_CONNECTION=sync</code></td><td><code>database</code> or <code>redis</code>, with workers</td></tr><tr><td>Scheduler</td><td>None</td><td><code>schedule:run</code> on exactly one server</td></tr><tr><td>Media on the default disk</td><td>The <code>public</code> disk, <code>storage/app/public</code></td><td>Amazon S3 or Cloudflare R2, or a shared volume</td></tr><tr><td>Files on the local disks</td><td><code>storage/app/private</code> and <code>storage/app/public</code></td><td>A shared volume</td></tr><tr><td>Search</td><td>The database</td><td>One Elasticsearch cluster</td></tr></tbody></table><h2 id="step-1-share-sessions-and-caches" tabindex="-1">Step 1: Share Sessions and Caches <a class="header-anchor" href="#step-1-share-sessions-and-caches" aria-label="Permalink to &quot;Step 1: Share Sessions and Caches&quot;">​</a></h2><p>Point every server at the same database, and keep sessions and the application cache in the shared database or Redis. Any server can then handle any request, so sticky sessions on the load balancer are optional.</p><p>The application cache holds the repository cache&#39;s reads and generation tokens, the catalog API responses and their version, the search engine&#39;s last connection verdict and the <code>queue:restart</code> signal. With a <code>file</code> store, a configuration saved on one server bumps the repository cache token on that server only, and the others keep serving the old values until their cached reads expire.</p><p>The full page cache defaults to a <code>file</code> store too, and its listeners run on the server that handled the change. Give it a shared store of its own; see <a href="./configure-fpc.html#choose-where-pages-are-stored">Configure Full Page Cache</a>.</p><h2 id="step-2-share-maintenance-mode" tabindex="-1">Step 2: Share Maintenance Mode <a class="header-anchor" href="#step-2-share-maintenance-mode" aria-label="Permalink to &quot;Step 2: Share Maintenance Mode&quot;">​</a></h2><p>Laravel&#39;s maintenance mode is a file on each server by default, so <code>php artisan down</code>, <code>php artisan up</code> and saving a channel reach only the server that ran them. Saving a channel in the admin switches maintenance mode on or off for the whole application from that channel&#39;s maintenance setting (<code>Webkul\\Admin\\Http\\Controllers\\Settings\\ChannelController</code>). Store it in a cache instead:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">APP_MAINTENANCE_DRIVER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=cache</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">APP_MAINTENANCE_STORE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=database</span></span></code></pre></div><p>The flag is kept under <code>illuminate:foundation:down</code> in that store, or in the default cache store when <code>APP_MAINTENANCE_STORE</code> is empty. <code>php artisan cache:clear</code>, <code>optimize:clear</code> and <strong>Clear All Cache</strong> flush the default cache store, so they lift maintenance mode when it&#39;s kept in the same store. Point <code>APP_MAINTENANCE_STORE</code> at a different shared store, such as <code>database</code> when <code>CACHE_STORE=redis</code>.</p><p>The admin stays reachable in maintenance mode: <code>Webkul\\Core\\Http\\Middleware\\PreventRequestsDuringMaintenance</code> lets requests under the admin URL through.</p><p><a id="queue-and-scheduler"></a></p><h2 id="step-3-run-the-queue-and-the-scheduler" tabindex="-1">Step 3: Run the Queue and the Scheduler <a class="header-anchor" href="#step-3-run-the-queue-and-the-scheduler" aria-label="Permalink to &quot;Step 3: Run the Queue and the Scheduler&quot;">​</a></h2><p>Workers pull jobs from the shared queue, so they can run on any server, or on servers of their own. Run them with <code>--queue=default,broadcastable</code>, as described in <a href="./../advanced/queue-jobs-scheduling.html#running-workers-in-production">Queues, Jobs and Scheduling</a>.</p><p>Run the scheduler&#39;s cron entry on one server only. Bagisto registers its tasks without <code>onOneServer()</code>, so a cron entry on every server runs <code>invoice:cron</code>, <code>campaign:process</code> and the other tasks once per server.</p><p><a id="files"></a></p><h2 id="step-4-share-files" tabindex="-1">Step 4: Share Files <a class="header-anchor" href="#step-4-share-files" aria-label="Permalink to &quot;Step 4: Share Files&quot;">​</a></h2><p>Product, category and theme media go to the default disk. Switch it to Amazon S3 or Cloudflare R2 before adding servers; see <a href="./../advanced/file-storage.html">File Storage</a>. Files already uploaded aren&#39;t moved for you.</p><p>Some files stay on a local disk whatever the default is, so share those directories between servers:</p><ul><li><strong><code>storage/app/private</code></strong>: import files, validation fragments, downloaded import images, import error reports and downloadable product link files. Import jobs read their files by path on the server whose worker runs them.</li><li><strong><code>storage/app/public</code></strong>: generated sitemaps, which <code>Webkul\\Sitemap\\Jobs\\ProcessSitemap</code> writes to the <code>public</code> disk. <code>SitemapController</code> lists the files on its own server and links them under <code>/storage/</code>, so share the directory and run <code>php artisan storage:link</code> on every server, even when media are on S3 or R2.</li></ul><h2 id="step-5-set-up-the-servers-behind-the-load-balancer" tabindex="-1">Step 5: Set Up the Servers Behind the Load Balancer <a class="header-anchor" href="#step-5-set-up-the-servers-behind-the-load-balancer" aria-label="Permalink to &quot;Step 5: Set Up the Servers Behind the Load Balancer&quot;">​</a></h2><ul><li><strong>HTTPS.</strong> <code>bootstrap/app.php</code> calls <code>$middleware-&gt;trustProxies(at: &#39;*&#39;)</code>, so Bagisto trusts the <code>X-Forwarded-*</code> headers from any address and builds <code>https://</code> URLs when the load balancer terminates TLS. Because any address is trusted, let only the load balancer reach the web servers.</li><li><strong><code>APP_URL</code> and <code>APP_KEY</code>.</strong> Set <code>APP_URL</code> to the public HTTPS address, and use the same <code>APP_KEY</code> on every server, or sessions and encrypted values from one server can&#39;t be read on another.</li><li><strong>Health checks.</strong> <code>bootstrap/app.php</code> registers Laravel&#39;s health route at <code>/up</code>. It carries no route middleware, answers <code>200</code> whenever the application boots, even in maintenance mode, and doesn&#39;t check the database, cache or queue. Point the load balancer&#39;s health check at it rather than at the home page, which the full page cache may answer.</li></ul><h2 id="step-6-deploy-to-every-server" tabindex="-1">Step 6: Deploy to Every Server <a class="header-anchor" href="#step-6-deploy-to-every-server" aria-label="Permalink to &quot;Step 6: Deploy to Every Server&quot;">​</a></h2><ol><li>Put the store into maintenance mode once with <code>php artisan down</code>.</li><li>Put the same code, <code>vendor</code> directory and built theme assets on every server.</li><li>Run <code>php artisan migrate --force</code> once, from one server.</li><li>Run <code>php artisan optimize</code> on every server, since the configuration, route, event and view caches are files.</li><li>Run <code>php artisan queue:restart</code> once. The restart signal is stored in the shared cache, so every worker picks it up.</li><li>On <a href="./configure-laravel-octane.html">Octane</a>, run <code>php artisan octane:reload</code> on every server.</li><li>Bring the store back once with <code>php artisan up</code>.</li></ol><h2 id="test-it" tabindex="-1">Test It <a class="header-anchor" href="#test-it" aria-label="Permalink to &quot;Test It&quot;">​</a></h2><ol><li>Run <code>php artisan about</code> on each server, and confirm the session, cache and queue drivers are the shared ones and that <code>public/storage</code> is linked.</li><li>Request <code>/up</code> on each server; it answers <code>200</code>.</li><li>Save a product in the admin, then request its page as a guest through the load balancer several times. Every response shows the change, whichever server answers.</li></ol><h2 id="example-on-aws" tabindex="-1">Example on AWS <a class="header-anchor" href="#example-on-aws" aria-label="Permalink to &quot;Example on AWS&quot;">​</a></h2><p>The same layout with AWS services:</p><ol><li><strong>Database.</strong> Create an Amazon RDS instance running MySQL 8.0, MariaDB 10.11 or PostgreSQL 16, in private subnets, with a security group that admits the web servers only. Set <code>DB_HOST</code> to its endpoint.</li><li><strong>Redis.</strong> Create an Amazon ElastiCache cluster with a Redis-compatible engine for sessions, the caches and the queue.</li><li><strong>Media.</strong> Create an S3 bucket and credentials that can read and write it. Enter them in the Amazon S3 settings of the <strong>File Management</strong> configuration section, fill in the bucket&#39;s public or CDN URL, and choose Amazon S3 as the default driver in its <strong>General</strong> settings.</li><li><strong>Shared directories.</strong> Create an Amazon EFS file system and mount it on every web server for <code>storage/app/private</code> and <code>storage/app/public</code>.</li><li><strong>Web servers.</strong> Install Bagisto on one EC2 instance, create a launch template from it, and run it in an Auto Scaling group across at least two Availability Zones.</li><li><strong>Target group.</strong> Create a target group for the instances on the web server&#39;s port, with <code>/up</code> as the health check path.</li><li><strong>Load balancer.</strong> Create an internet-facing Application Load Balancer with an HTTPS listener on port 443 that uses a certificate from AWS Certificate Manager and forwards to the target group, and an HTTP listener on port 80 that redirects to HTTPS.</li><li><strong>DNS.</strong> Point the store&#39;s domain at the load balancer&#39;s DNS name.</li><li><strong>Background work.</strong> Run the scheduler&#39;s cron entry on one instance, and queue workers on the web servers or on instances of their own.</li></ol><h2 id="things-to-watch" tabindex="-1">Things to Watch <a class="header-anchor" href="#things-to-watch" aria-label="Permalink to &quot;Things to Watch&quot;">​</a></h2><ul><li><strong>One cron entry.</strong> A second server running the scheduler duplicates every scheduled task.</li><li><strong>Per-server state.</strong> Any <code>file</code> store for sessions, the application cache, the page cache or maintenance mode serves stale or missing data from the other servers.</li><li><strong>Local directories.</strong> An import started on one server fails on a worker that can&#39;t see its file, and a sitemap is only listed by the server that wrote it, unless <code>storage/app</code> is shared.</li><li><strong>Cache Management actions</strong> such as <strong>Rebuild All Cache</strong> write the framework cache files of the server that handled the click only.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./configure-fpc.html">Configure Full Page Cache</a>: a shared store for the page cache.</li><li><a href="./../advanced/queue-jobs-scheduling.html">Queues, Jobs and Scheduling</a>: workers and the scheduler.</li><li><a href="./../advanced/file-storage.html">File Storage</a>: moving media to Amazon S3 or Cloudflare R2.</li><li><a href="./configure-laravel-octane.html">Configure Laravel Octane</a>: long-running workers on each server.</li></ul>`,36)]))}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
